export const DISH_RECIPES = [{"id":"gheymeh_bademjan","titleEn":"Gheymeh with fried eggplant","titleFa":"قیمه بادمجان","tag":"persian","minutes":150,"meal":"lunch","serving":300,"cookedWeight":1650,"portions":5.5,"ingredients":[{"foodId":"lamb_stew","grams":450},{"foodId":"split_peas","grams":250},{"foodId":"eggplant","grams":500},{"foodId":"onion","grams":150},{"foodId":"tomato_paste","grams":50},{"foodId":"vegetable_oil","grams":70},{"foodId":"dried_lime","grams":12},{"foodId":"water","grams":400}],"stepsEn":["Fry the onion in half the oil until golden; add the meat and tomato paste.","Add water and dried limes and simmer 90 minutes; add the cooked split peas for the last 20.","Fry the sliced eggplant in the rest of the oil and lay it on top."],"stepsFa":["پیاز را در نصف روغن طلایی کن؛ گوشت و رب را اضافه کن.","آب و لیمو عمانی را بریز و ۹۰ دقیقه آرام بپز؛ ۲۰ دقیقه‌ی آخر لپه‌ی پخته را اضافه کن.","بادمجان حلقه‌شده را در باقی روغن سرخ کن و روی خورش بچین."],"diet":"meat","pair":"rice","planSub":"stew"},
{"id":"khoresh_bademjan","titleEn":"Eggplant stew","titleFa":"خورش بادمجان","tag":"persian","minutes":150,"meal":"lunch","serving":300,"cookedWeight":1800,"portions":6,"ingredients":[{"foodId":"lamb_stew","grams":450},{"foodId":"eggplant","grams":700},{"foodId":"onion","grams":200},{"foodId":"tomato","grams":300},{"foodId":"tomato_paste","grams":35},{"foodId":"verjuice","grams":60},{"foodId":"vegetable_oil","grams":80},{"foodId":"saffron_brewed","grams":15},{"foodId":"water","grams":350}],"stepsEn":["Fry the sliced onion in a third of the oil until golden, add the meat and tomato paste and fry 2 minutes.","Add the water and simmer covered for 90 minutes.","Peel the eggplants, halve them lengthwise, salt them for 20 minutes, then fry them golden in the rest of the oil.","Lay the eggplant and halved tomatoes on the stew, add the verjuice and saffron and simmer 30 minutes more."],"stepsFa":["پیاز خلالی را در یک‌سوم روغن طلایی کن، گوشت و رب را اضافه کن و ۲ دقیقه تفت بده.","آب را بریز و با درِ بسته ۹۰ دقیقه آرام بپز.","بادمجان‌ها را پوست بگیر، از طول نصف کن، ۲۰ دقیقه نمک بزن و بعد در باقی روغن طلایی سرخ کن.","بادمجان و گوجه‌های نصف‌شده را روی خورش بچین، آبغوره و زعفران را اضافه کن و ۳۰ دقیقه‌ی دیگر بپز."],"diet":"meat","pair":"rice","planSub":"stew"},
{"id":"khoresh_karafs","titleEn":"Celery stew","titleFa":"خورش کرفس","tag":"persian","minutes":150,"meal":"lunch","serving":300,"cookedWeight":1550,"portions":5.2,"ingredients":[{"foodId":"beef_stew","grams":400},{"foodId":"celery","grams":600},{"foodId":"parsley","grams":150},{"foodId":"onion","grams":150},{"foodId":"vegetable_oil","grams":60},{"foodId":"lemon_juice","grams":40},{"foodId":"saffron_brewed","grams":10},{"foodId":"water","grams":450}],"stepsEn":["Fry the onion in a little of the oil, add the meat and turmeric, then the water, and simmer 90 minutes.","Cut the celery into 3 cm pieces and fry it in some of the oil for 10 minutes; fry the chopped parsley (and a spoon of dried mint) separately in the rest.","Add the celery and herbs to the meat with the lemon juice and saffron and simmer 40 minutes until the celery is tender."],"stepsFa":["پیاز را در کمی روغن تفت بده، گوشت و زردچوبه و بعد آب را اضافه کن و ۹۰ دقیقه آرام بپز.","کرفس را ۳ سانتی خرد کن و ۱۰ دقیقه در کمی روغن تفت بده؛ جعفری خردشده (و یک قاشق نعناع خشک) را جدا در باقی روغن سرخ کن.","کرفس و سبزی را با آبلیمو و زعفران به گوشت اضافه کن و ۴۰ دقیقه بپز تا کرفس نرم شود."],"diet":"meat","pair":"rice","planSub":"stew"},
{"id":"khoresh_bamieh","titleEn":"Okra stew","titleFa":"خورش بامیه","tag":"persian","minutes":140,"meal":"lunch","serving":300,"cookedWeight":1550,"portions":5.2,"ingredients":[{"foodId":"beef_stew","grams":400},{"foodId":"okra","grams":500},{"foodId":"onion","grams":150},{"foodId":"garlic","grams":20},{"foodId":"tomato","grams":200},{"foodId":"tomato_paste","grams":50},{"foodId":"lemon_juice","grams":40},{"foodId":"vegetable_oil","grams":60},{"foodId":"water","grams":400}],"stepsEn":["Fry the onion and garlic in half the oil, add the meat and tomato paste, then the water, and simmer 90 minutes.","Trim the okra tops and fry them in the rest of the oil for 5 minutes without breaking them.","Add the okra, chopped tomato and lemon juice and simmer gently for 30 minutes, stirring as little as possible."],"stepsFa":["پیاز و سیر را در نصف روغن تفت بده، گوشت و رب و بعد آب را اضافه کن و ۹۰ دقیقه آرام بپز.","سرِ بامیه‌ها را بگیر و در باقی روغن ۵ دقیقه تفت بده، طوری که نشکنند.","بامیه، گوجه‌ی خردشده و آبلیمو را اضافه کن و ۳۰ دقیقه آرام بپز و تا می‌شود هم نزن."],"diet":"meat","pair":"rice","planSub":"stew"},
{"id":"khoresh_aloo_esfenaj","titleEn":"Spinach and prune stew","titleFa":"خورش آلو اسفناج","tag":"persian","minutes":140,"meal":"lunch","serving":300,"cookedWeight":1400,"portions":4.7,"ingredients":[{"foodId":"lamb_stew","grams":380},{"foodId":"spinach","grams":800},{"foodId":"prunes","grams":120},{"foodId":"onion","grams":150},{"foodId":"vegetable_oil","grams":50},{"foodId":"verjuice","grams":50},{"foodId":"sugar","grams":10},{"foodId":"water","grams":300}],"stepsEn":["Fry the onion in half the oil, add the meat and turmeric, then the water, and simmer 90 minutes.","Wash and chop the spinach and fry it in the rest of the oil until its water is gone.","Add the spinach, prunes, verjuice and sugar to the meat and simmer 30 minutes until the prunes are soft."],"stepsFa":["پیاز را در نصف روغن تفت بده، گوشت و زردچوبه و بعد آب را اضافه کن و ۹۰ دقیقه آرام بپز.","اسفناج را بشور، خرد کن و در باقی روغن تفت بده تا آبش کشیده شود.","اسفناج، آلو، آبغوره و شکر را به گوشت اضافه کن و ۳۰ دقیقه بپز تا آلو نرم شود."],"diet":"meat","pair":"rice","planSub":"stew"},
{"id":"khoresh_loobia_sabz","titleEn":"Green bean stew","titleFa":"خورش لوبیا سبز","tag":"persian","minutes":130,"meal":"lunch","serving":300,"cookedWeight":1500,"portions":5,"ingredients":[{"foodId":"beef_stew","grams":400},{"foodId":"green_beans","grams":500},{"foodId":"onion","grams":150},{"foodId":"tomato","grams":250},{"foodId":"tomato_paste","grams":40},{"foodId":"vegetable_oil","grams":55},{"foodId":"water","grams":350}],"stepsEn":["Fry the onion in half the oil, add the meat, turmeric and tomato paste, then the water, and simmer 80 minutes.","Cut the green beans into 2 cm pieces and fry them in the rest of the oil for 10 minutes.","Add the beans and chopped tomato to the meat and simmer 30 minutes until the beans are tender."],"stepsFa":["پیاز را در نصف روغن تفت بده، گوشت، زردچوبه و رب و بعد آب را اضافه کن و ۸۰ دقیقه آرام بپز.","لوبیا سبز را ۲ سانتی خرد کن و ۱۰ دقیقه در باقی روغن تفت بده.","لوبیا و گوجه‌ی خردشده را به گوشت اضافه کن و ۳۰ دقیقه بپز تا لوبیا نرم شود."],"diet":"meat","pair":"rice","planSub":"stew"},
{"id":"khoresh_kadoo","titleEn":"Zucchini stew","titleFa":"خورش کدو","tag":"persian","minutes":130,"meal":"lunch","serving":300,"cookedWeight":1600,"portions":5.3,"ingredients":[{"foodId":"lamb_stew","grams":400},{"foodId":"zucchini","grams":700},{"foodId":"onion","grams":150},{"foodId":"tomato","grams":250},{"foodId":"tomato_paste","grams":40},{"foodId":"verjuice","grams":40},{"foodId":"vegetable_oil","grams":60},{"foodId":"water","grams":300}],"stepsEn":["Fry the onion in a little of the oil, add the meat, turmeric and tomato paste, then the water, and simmer 90 minutes.","Peel the zucchini, halve them lengthwise and fry them golden in the rest of the oil.","Lay the zucchini and sliced tomato on the stew, add the verjuice and simmer 20 minutes."],"stepsFa":["پیاز را در کمی روغن تفت بده، گوشت، زردچوبه و رب و بعد آب را اضافه کن و ۹۰ دقیقه آرام بپز.","کدوها را پوست بگیر، از طول نصف کن و در باقی روغن طلایی سرخ کن.","کدو و گوجه‌ی حلقه‌شده را روی خورش بچین، آبغوره را بریز و ۲۰ دقیقه بپز."],"diet":"meat","pair":"rice","planSub":"stew"},
{"id":"zereshk_polo_morgh","titleEn":"Barberry rice with chicken","titleFa":"زرشک پلو با مرغ","tag":"persian","minutes":150,"meal":"lunch","serving":400,"cookedWeight":2100,"portions":5.3,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":800},{"foodId":"chicken_whole","grams":600},{"foodId":"onion","grams":150},{"foodId":"tomato_paste","grams":25},{"foodId":"barberries","grams":40},{"foodId":"sugar","grams":10},{"foodId":"butter","grams":25},{"foodId":"vegetable_oil","grams":45},{"foodId":"saffron_brewed","grams":25},{"foodId":"pistachio","grams":15}],"stepsEn":["Soak the rice for 2 hours, parboil it in salted water for 8 minutes, drain, and steam it 50 minutes with half the oil and a little water.","Fry the onion in the rest of the oil, add the chicken, tomato paste, turmeric and a glass of water and simmer 45 minutes until the sauce thickens.","Fry the barberries very briefly in the butter with the sugar and a spoon of the saffron.","Mix some of the rice with the rest of the saffron and serve topped with the barberries and pistachio slivers, the chicken on the side."],"stepsFa":["برنج را ۲ ساعت خیس کن، ۸ دقیقه در آب نمک آب‌پز کن، آبکش کن و با نصف روغن و کمی آب ۵۰ دقیقه دم کن.","پیاز را در باقی روغن تفت بده، مرغ، رب، زردچوبه و یک لیوان آب را اضافه کن و ۴۵ دقیقه بپز تا سس غلیظ شود.","زرشک را با شکر و یک قاشق زعفران خیلی کوتاه در کره تفت بده.","کمی از برنج را با باقی زعفران مخلوط کن و پلو را با زرشک و خلال پسته رویش و مرغ کنارش سرو کن."],"diet":"meat","allergens":["dairy","nuts"],"pair":"none","planSub":"rice"},
{"id":"baghali_polo_mahicheh","titleEn":"Fava bean and dill rice with lamb shank","titleFa":"باقالی پلو با ماهیچه","tag":"persian","minutes":240,"meal":"lunch","serving":500,"cookedWeight":2350,"portions":4.7,"ingredients":[{"foodId":"lamb_shank","grams":720},{"foodId":"rice_raw","grams":400},{"foodId":"water","grams":700},{"foodId":"fava_beans","grams":300},{"foodId":"dill","grams":100},{"foodId":"onion","grams":120},{"foodId":"butter","grams":30},{"foodId":"vegetable_oil","grams":45},{"foodId":"saffron_brewed","grams":20}],"stepsEn":["Fry the onion in half the oil, brown the lamb shanks with turmeric, add water to cover and simmer 3 hours until tender.","Parboil the soaked rice for 7 minutes, add the fava beans for the last minute and drain.","Layer the rice and beans with the chopped dill in the pot and steam 50 minutes with the rest of the oil.","Serve with the butter and saffron on top and a shank with its sauce on each plate."],"stepsFa":["پیاز را در نصف روغن تفت بده، ماهیچه‌ها را با زردچوبه سرخ کن، آب بریز تا رویشان را بگیرد و ۳ ساعت بپز تا نرم شوند.","برنجِ خیس‌خورده را ۷ دقیقه آب‌پز کن، دقیقه‌ی آخر باقالی را اضافه کن و آبکش کن.","برنج و باقالی را لایه‌لایه با شوید خردشده در قابلمه بریز و با باقی روغن ۵۰ دقیقه دم کن.","با کره و زعفران رویش سرو کن و در هر بشقاب یک ماهیچه با سسش بگذار."],"diet":"meat","allergens":["dairy"],"pair":"none","planSub":"rice"},
{"id":"adas_polo","titleEn":"Lentil rice with raisins and dates","titleFa":"عدس پلو","tag":"persian","minutes":90,"meal":"lunch","serving":400,"cookedWeight":1800,"portions":4.5,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":700},{"foodId":"lentils","grams":300},{"foodId":"onion","grams":200},{"foodId":"raisins","grams":80},{"foodId":"dates","grams":80},{"foodId":"butter","grams":30},{"foodId":"vegetable_oil","grams":50},{"foodId":"saffron_brewed","grams":15}],"stepsEn":["Parboil the soaked rice for 7 minutes, drain, and mix it with the cooked lentils.","Steam the rice and lentils for 45 minutes with half the oil.","Fry the sliced onion golden in the rest of the oil, then add the raisins and pitted dates for a minute.","Serve the polo topped with the onion, raisins and dates, the butter and saffron."],"stepsFa":["برنج خیس‌خورده را ۷ دقیقه آب‌پز و آبکش کن و با عدس پخته مخلوط کن.","برنج و عدس را با نصف روغن ۴۵ دقیقه دم کن.","پیاز خلالی را در باقی روغن طلایی کن و کشمش و خرمای بی‌هسته را یک دقیقه با آن تفت بده.","پلو را با پیاز داغ، کشمش و خرما و کره و زعفران رویش سرو کن."],"diet":"vegetarian","allergens":["dairy"],"pair":"none","planSub":"rice"},
{"id":"loobia_polo","titleEn":"Green bean rice with meat","titleFa":"لوبیا پلو","tag":"persian","minutes":100,"meal":"lunch","serving":400,"cookedWeight":2000,"portions":5,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":700},{"foodId":"green_beans","grams":400},{"foodId":"beef_ground_regular","grams":300},{"foodId":"onion","grams":150},{"foodId":"tomato_paste","grams":60},{"foodId":"vegetable_oil","grams":70},{"foodId":"saffron_brewed","grams":10}],"stepsEn":["Fry the onion in half the oil, add the ground meat and brown it, then the tomato paste, turmeric and cinnamon.","Add the green beans cut in 1 cm pieces and fry for 10 minutes.","Parboil the soaked rice for 7 minutes, drain, and layer it with the bean mixture in the pot.","Steam 50 minutes with the rest of the oil and serve with the saffron on top."],"stepsFa":["پیاز را در نصف روغن تفت بده، گوشت چرخ‌کرده را اضافه کن و سرخ کن، بعد رب، زردچوبه و دارچین را بزن.","لوبیا سبزِ یک‌سانتی خردشده را اضافه کن و ۱۰ دقیقه تفت بده.","برنج خیس‌خورده را ۷ دقیقه آب‌پز و آبکش کن و لایه‌لایه با مواد لوبیا در قابلمه بریز.","با باقی روغن ۵۰ دقیقه دم کن و با زعفران رویش سرو کن."],"diet":"meat","pair":"none","planSub":"rice"},
{"id":"estamboli_polo","titleEn":"Tomato and potato rice","titleFa":"استامبولی پلو","tag":"persian","minutes":80,"meal":"lunch","serving":400,"cookedWeight":2150,"portions":5.4,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":650},{"foodId":"potato","grams":400},{"foodId":"tomato","grams":300},{"foodId":"tomato_paste","grams":60},{"foodId":"onion","grams":150},{"foodId":"beef_ground_regular","grams":250},{"foodId":"vegetable_oil","grams":70}],"stepsEn":["Fry the onion in half the oil, add the ground meat, then the tomato paste, chopped tomato and turmeric.","Add the potato cubes, the rinsed rice and the water and boil until the water is almost gone.","Pour over the rest of the oil and steam on low heat for 45 minutes."],"stepsFa":["پیاز را در نصف روغن تفت بده، گوشت چرخ‌کرده و بعد رب، گوجه‌ی خردشده و زردچوبه را اضافه کن.","سیب‌زمینی مکعبی، برنجِ شسته و آب را اضافه کن و بجوشان تا آبش تقریباً کشیده شود.","باقی روغن را رویش بریز و روی حرارت کم ۴۵ دقیقه دم کن."],"diet":"meat","pair":"none","planSub":"rice"},
{"id":"sabzi_polo_mahi","titleEn":"Herb rice with fried fish","titleFa":"سبزی پلو با ماهی","tag":"persian","minutes":120,"meal":"lunch","serving":450,"cookedWeight":2150,"portions":4.8,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":700},{"foodId":"parsley","grams":100},{"foodId":"coriander","grams":80},{"foodId":"dill","grams":80},{"foodId":"leek","grams":100},{"foodId":"garlic","grams":20},{"foodId":"vegetable_oil","grams":100},{"foodId":"white_fish","grams":600},{"foodId":"flour_white","grams":30}],"stepsEn":["Parboil the soaked rice for 7 minutes, drain, and mix in the finely chopped herbs and garlic.","Steam the rice for 50 minutes with half the oil, for a crisp tahdig.","Dust the fish pieces with the flour and turmeric and fry them golden in the rest of the oil, about 4 minutes a side.","Serve the herb rice with a piece of fish and a squeeze of lemon."],"stepsFa":["برنج خیس‌خورده را ۷ دقیقه آب‌پز و آبکش کن و سبزی ریز خردشده و سیر را با آن مخلوط کن.","برنج را با نصف روغن ۵۰ دقیقه دم کن تا ته‌دیگ ترد بدهد.","تکه‌های ماهی را در آرد و زردچوبه بغلتان و در باقی روغن، هر طرف حدود ۴ دقیقه طلایی سرخ کن.","سبزی پلو را با یک تکه ماهی و کمی آب لیمو سرو کن."],"diet":"fish","allergens":["fish","gluten"],"pair":"none","planSub":"rice"},
{"id":"kalam_polo_shirazi","titleEn":"Shirazi cabbage rice with meatballs","titleFa":"کلم پلو شیرازی","tag":"persian","minutes":110,"meal":"lunch","serving":400,"cookedWeight":2050,"portions":5.1,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":700},{"foodId":"cabbage","grams":500},{"foodId":"beef_ground_regular_raw","grams":300},{"foodId":"dill","grams":50},{"foodId":"leek","grams":50},{"foodId":"onion","grams":150},{"foodId":"vegetable_oil","grams":70},{"foodId":"saffron_brewed","grams":15}],"stepsEn":["Grate half the onion into the ground meat, season it and roll it into small meatballs; fry them in some of the oil.","Fry the rest of the onion and the chopped cabbage in more oil until golden, then add the chopped herbs.","Parboil the soaked rice for 7 minutes, drain, and layer it with the cabbage and meatballs in the pot.","Steam 50 minutes with the rest of the oil and serve with the saffron on top."],"stepsFa":["نصف پیاز را در گوشت چرخ‌کرده رنده کن، مزه‌دار کن و قلقلی‌های کوچک درست کن؛ در کمی روغن سرخشان کن.","باقی پیاز و کلم خردشده را در کمی روغن تفت بده تا طلایی شوند، بعد سبزی خردشده را اضافه کن.","برنج خیس‌خورده را ۷ دقیقه آب‌پز و آبکش کن و لایه‌لایه با کلم و قلقلی‌ها در قابلمه بریز.","با باقی روغن ۵۰ دقیقه دم کن و با زعفران رویش سرو کن."],"diet":"meat","pair":"none","planSub":"rice"},
{"id":"reshteh_polo","titleEn":"Noodle rice with raisins and dates","titleFa":"رشته پلو","tag":"persian","minutes":100,"meal":"lunch","serving":400,"cookedWeight":1750,"portions":4.4,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":850},{"foodId":"noodle_polo","grams":150},{"foodId":"raisins","grams":60},{"foodId":"dates","grams":60},{"foodId":"onion","grams":150},{"foodId":"butter","grams":40},{"foodId":"vegetable_oil","grams":40},{"foodId":"saffron_brewed","grams":15}],"stepsEn":["Toast the noodles in a dry pan until light brown.","Parboil the soaked rice for 5 minutes, add the noodles for the last 2 minutes and drain.","Steam for 50 minutes with the oil.","Fry the sliced onion in the butter, add the raisins and dates, and serve them on the polo with the saffron."],"stepsFa":["رشته را در تابه‌ی خشک تفت بده تا کمی قهوه‌ای شود.","برنج خیس‌خورده را ۵ دقیقه آب‌پز کن، ۲ دقیقه‌ی آخر رشته را اضافه کن و آبکش کن.","با روغن ۵۰ دقیقه دم کن.","پیاز خلالی را در کره تفت بده، کشمش و خرما را اضافه کن و با زعفران روی پلو سرو کن."],"diet":"vegetarian","allergens":["gluten","dairy"],"pair":"none","planSub":"rice"},
{"id":"dampokhtak","titleEn":"Turmeric rice with fava beans","titleFa":"دمپختک","tag":"persian","minutes":70,"meal":"lunch","serving":400,"cookedWeight":1720,"portions":4.3,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":800},{"foodId":"fava_beans","grams":300},{"foodId":"onion","grams":150},{"foodId":"vegetable_oil","grams":60},{"foodId":"dill","grams":30}],"stepsEn":["Fry the onion in the oil with plenty of turmeric.","Add the rinsed rice, the cooked fava beans and the water and boil until the water is almost gone.","Stir in the dill, cover and steam 45 minutes on low heat."],"stepsFa":["پیاز را با زردچوبه‌ی فراوان در روغن تفت بده.","برنجِ شسته، باقلای پخته و آب را اضافه کن و بجوشان تا آبش تقریباً کشیده شود.","شوید را هم بزن، درش را بگذار و روی حرارت کم ۴۵ دقیقه دم کن."],"diet":"vegan","pair":"none","planSub":"rice"},
{"id":"meygoo_polo","titleEn":"Bushehri shrimp rice","titleFa":"میگو پلو","tag":"persian","minutes":80,"meal":"lunch","serving":400,"cookedWeight":1950,"portions":4.9,"ingredients":[{"foodId":"rice_raw","grams":450},{"foodId":"water","grams":700},{"foodId":"shrimp","grams":500},{"foodId":"onion","grams":200},{"foodId":"garlic","grams":20},{"foodId":"coriander","grams":60},{"foodId":"tomato_paste","grams":30},{"foodId":"vegetable_oil","grams":70}],"stepsEn":["Fry the onion golden in half the oil, add the garlic, turmeric and Bushehri spice mix, then the shrimp, and fry 5 minutes.","Stir in the tomato paste and chopped coriander and cook 2 minutes more.","Parboil the soaked rice for 7 minutes, drain, and layer it with the shrimp mixture in the pot.","Steam 45 minutes with the rest of the oil."],"stepsFa":["پیاز را در نصف روغن طلایی کن، سیر، زردچوبه و ادویه‌ی بوشهری و بعد میگو را اضافه کن و ۵ دقیقه تفت بده.","رب و گشنیز خردشده را اضافه کن و ۲ دقیقه‌ی دیگر تفت بده.","برنج خیس‌خورده را ۷ دقیقه آب‌پز و آبکش کن و لایه‌لایه با مواد میگو در قابلمه بریز.","با باقی روغن ۴۵ دقیقه دم کن."],"diet":"fish","allergens":["shellfish"],"pair":"none","planSub":"rice"},
{"id":"makaroni","titleEn":"Persian macaroni with meat sauce","titleFa":"ماکارونی با گوشت","tag":"persian","minutes":90,"meal":"dinner","serving":400,"cookedWeight":2100,"portions":5.3,"ingredients":[{"foodId":"pasta","grams":1100},{"foodId":"beef_ground_regular","grams":350},{"foodId":"onion","grams":200},{"foodId":"tomato_paste","grams":80},{"foodId":"bell_pepper","grams":100},{"foodId":"vegetable_oil","grams":60},{"foodId":"water","grams":200},{"foodId":"potato","grams":200}],"stepsEn":["Fry the onion in half the oil, add the ground meat and brown it, then the tomato paste, chopped pepper, turmeric and the water; simmer 15 minutes.","Boil the pasta for 6 minutes (half-cooked) and drain.","Line the pot with the rest of the oil and potato slices, then layer the pasta and meat sauce on top.","Cover and steam 40 minutes on low heat until the potato tahdig is crisp."],"stepsFa":["پیاز را در نصف روغن تفت بده، گوشت چرخ‌کرده را سرخ کن، بعد رب، فلفل دلمه‌ای خردشده، زردچوبه و آب را اضافه کن و ۱۵ دقیقه بپز.","ماکارونی را ۶ دقیقه (نیم‌پز) آب‌پز و آبکش کن.","ته قابلمه را با باقی روغن و حلقه‌های سیب‌زمینی بپوشان و ماکارونی و سس گوشت را لایه‌لایه رویش بریز.","درش را بگذار و روی حرارت کم ۴۰ دقیقه دم کن تا ته‌دیگ سیب‌زمینی ترد شود."],"diet":"meat","allergens":["gluten"],"pair":"none","planSub":"rice"},
{"id":"kabab_barg","titleEn":"Kabab barg (lamb fillet kabab)","titleFa":"کباب برگ","tag":"persian","minutes":45,"meal":"dinner","serving":250,"cookedWeight":1000,"portions":4,"ingredients":[{"foodId":"lamb","grams":600},{"foodId":"onion","grams":60},{"foodId":"olive_oil","grams":20},{"foodId":"saffron_brewed","grams":10},{"foodId":"butter","grams":20},{"foodId":"tomato","grams":400}],"stepsEn":["Slice the lamb fillet thin, pound it flat and marinate it overnight in grated onion juice, the olive oil and half the saffron.","Thread the meat flat on wide skewers and the tomatoes on another skewer.","Grill over hot coals 3–4 minutes a side and brush with the butter melted with the rest of the saffron."],"stepsFa":["راسته‌ی گوسفندی را نازک برش بزن، با گوشت‌کوب پهن کن و یک شب در آب پیاز رنده‌شده، روغن زیتون و نصف زعفران بخوابان.","گوشت را صاف روی سیخ پهن بکش و گوجه‌ها را به سیخ دیگری بزن.","روی ذغال داغ هر طرف ۳ تا ۴ دقیقه کباب کن و با کره‌ی آب‌شده و باقی زعفران چرب کن."],"diet":"meat","allergens":["dairy"],"pair":"rice","planSub":"meat"},
{"id":"kabab_tabei","titleEn":"Pan kabab","titleFa":"کباب تابه‌ای","tag":"persian","minutes":35,"meal":"dinner","serving":200,"cookedWeight":740,"portions":3.7,"ingredients":[{"foodId":"beef_ground_regular_raw","grams":500},{"foodId":"onion","grams":150},{"foodId":"tomato","grams":300},{"foodId":"vegetable_oil","grams":25}],"stepsEn":["Grate the onion, squeeze out its juice and knead the pulp into the ground meat with salt, pepper and turmeric for 5 minutes.","Press the meat into a pan in an even layer, cut it into strips and cook 5 minutes a side over medium heat.","Fry the halved tomatoes in the oil next to the kabab and serve."],"stepsFa":["پیاز را رنده کن، آبش را بگیر و با نمک، فلفل و زردچوبه ۵ دقیقه با گوشت چرخ‌کرده ورز بده.","گوشت را یکدست در تابه پهن کن، نواری برش بزن و روی حرارت متوسط هر طرف ۵ دقیقه بپز.","گوجه‌های نصف‌شده را کنار کباب در روغن سرخ کن و سرو کن."],"diet":"meat","pair":"rice","planSub":"meat"},
{"id":"morgh_zaferani","titleEn":"Saffron braised chicken","titleFa":"مرغ زعفرانی","tag":"persian","minutes":70,"meal":"lunch","serving":250,"cookedWeight":1150,"portions":4.6,"ingredients":[{"foodId":"chicken_whole","grams":700},{"foodId":"onion","grams":250},{"foodId":"tomato_paste","grams":30},{"foodId":"lemon_juice","grams":30},{"foodId":"saffron_brewed","grams":30},{"foodId":"vegetable_oil","grams":40},{"foodId":"water","grams":200}],"stepsEn":["Fry the sliced onion golden in the oil, add the chicken pieces and turmeric and brown them on all sides.","Add the tomato paste, then the water; cover and simmer 45 minutes.","Add the saffron and lemon juice and cook 10 minutes more, until the sauce is thick."],"stepsFa":["پیاز خلالی را در روغن طلایی کن، تکه‌های مرغ و زردچوبه را اضافه کن و همه طرفشان را سرخ کن.","رب و بعد آب را اضافه کن؛ درش را بگذار و ۴۵ دقیقه آرام بپز.","زعفران و آبلیمو را بریز و ۱۰ دقیقه‌ی دیگر بپز تا سس غلیظ شود."],"diet":"meat","pair":"rice","planSub":"poultry"},
{"id":"mahi_sorkhkardeh","titleEn":"Pan-fried fish","titleFa":"ماهی سرخ‌کرده","tag":"persian","minutes":30,"meal":"lunch","serving":200,"cookedWeight":900,"portions":4.5,"ingredients":[{"foodId":"white_fish","grams":800},{"foodId":"flour_white","grams":40},{"foodId":"vegetable_oil","grams":70},{"foodId":"lemon_juice","grams":30}],"stepsEn":["Cut the fish into pieces, season with salt, pepper and turmeric and roll them in the flour.","Fry in hot oil over medium heat, 4–5 minutes a side, until golden.","Drain on paper and serve with the lemon juice."],"stepsFa":["ماهی را تکه کن، با نمک، فلفل و زردچوبه مزه‌دار کن و در آرد بغلتان.","در روغن داغ روی حرارت متوسط، هر طرف ۴ تا ۵ دقیقه سرخ کن تا طلایی شود.","روی دستمال کاغذی بگذار تا روغنش گرفته شود و با آبلیمو سرو کن."],"diet":"fish","allergens":["fish","gluten"],"pair":"rice","planSub":"fish"},
{"id":"ghezel_ala_kababi","titleEn":"Grilled trout","titleFa":"ماهی قزل‌آلا کبابی","tag":"persian","minutes":40,"meal":"dinner","serving":200,"cookedWeight":780,"portions":3.9,"ingredients":[{"foodId":"trout","grams":700},{"foodId":"butter","grams":30},{"foodId":"lemon_juice","grams":40},{"foodId":"garlic","grams":15},{"foodId":"saffron_brewed","grams":10}],"stepsEn":["Clean the trout, make a few cuts in the skin and rub them with the crushed garlic, lemon juice, saffron, salt and pepper.","Grill over coals or bake at 200 °C for 20 minutes, turning once.","Brush with the melted butter and serve."],"stepsFa":["ماهی قزل‌آلا را تمیز کن، روی پوستش چند برش بزن و با سیر له‌شده، آبلیمو، زعفران، نمک و فلفل مزه‌دار کن.","روی ذغال کباب کن یا در فر ۲۰۰ درجه ۲۰ دقیقه بپز و یک بار برگردان.","با کره‌ی آب‌شده چرب کن و سرو کن."],"diet":"fish","allergens":["fish","dairy"],"pair":"rice","planSub":"fish"},
{"id":"shami_kabab","titleEn":"Shami kabab (meat and split pea patties)","titleFa":"شامی کباب","tag":"persian","minutes":120,"meal":"dinner","serving":180,"cookedWeight":780,"portions":4.3,"ingredients":[{"foodId":"beef_stew","grams":300},{"foodId":"split_peas","grams":300},{"foodId":"onion","grams":100},{"foodId":"egg","grams":100},{"foodId":"vegetable_oil","grams":60}],"stepsEn":["Grind the cooked meat and split peas together with the onion until smooth.","Knead in the eggs, turmeric, salt and pepper.","Shape flat oval patties with a hole in the middle and fry them in the oil, 3–4 minutes a side, until brown."],"stepsFa":["گوشت و لپه‌ی پخته را با پیاز چرخ کن تا یکدست شود.","تخم‌مرغ‌ها، زردچوبه، نمک و فلفل را اضافه کن و ورز بده.","به شکل بیضی‌های پهن با سوراخی در وسط درآور و در روغن، هر طرف ۳ تا ۴ دقیقه سرخ کن تا قهوه‌ای شود."],"diet":"meat","allergens":["egg"],"pair":"bread","planSub":"meat"},
{"id":"koofteh_tabrizi","titleEn":"Tabriz kofteh (stuffed meatball in broth)","titleFa":"کوفته تبریزی","tag":"persian","minutes":150,"meal":"lunch","serving":450,"cookedWeight":2100,"portions":4.7,"ingredients":[{"foodId":"beef_ground_regular_raw","grams":500},{"foodId":"rice_raw","grams":100},{"foodId":"split_peas","grams":150},{"foodId":"parsley","grams":50},{"foodId":"dill","grams":20},{"foodId":"leek","grams":50},{"foodId":"onion","grams":250},{"foodId":"egg","grams":150},{"foodId":"walnuts","grams":40},{"foodId":"prunes","grams":60},{"foodId":"barberries","grams":20},{"foodId":"tomato_paste","grams":40},{"foodId":"vegetable_oil","grams":40},{"foodId":"water","grams":800}],"stepsEn":["Cook the rice soft in a little water; mix it with the ground meat, cooked split peas, one grated onion, the chopped herbs and one egg, and knead for 10 minutes.","Hard-boil the other eggs; wrap each kofteh around an egg, prunes, walnuts and barberries and close it into a large ball.","Fry the rest of the onion in the oil, add the tomato paste and the water and bring to a boil.","Lower the koftehs into the sauce and simmer gently for 1 hour, spooning sauce over them."],"stepsFa":["برنج را در کمی آب نرم بپز؛ با گوشت چرخ‌کرده، لپه‌ی پخته، یک پیاز رنده‌شده، سبزی خردشده و یک تخم‌مرغ مخلوط کن و ۱۰ دقیقه ورز بده.","باقی تخم‌مرغ‌ها را سفت بپز؛ وسط هر کوفته یک تخم‌مرغ، آلو، گردو و زرشک بگذار و به شکل یک گلوله‌ی بزرگ ببند.","باقی پیاز را در روغن تفت بده، رب و آب را اضافه کن و بگذار بجوشد.","کوفته‌ها را آرام در سس بگذار و ۱ ساعت روی حرارت کم بپز و گاهی از سس رویشان بریز."],"diet":"meat","allergens":["egg","nuts"],"pair":"bread","planSub":"meat"},
{"id":"dolmeh_felfel","titleEn":"Stuffed bell peppers","titleFa":"دلمه فلفل","tag":"persian","minutes":100,"meal":"lunch","serving":350,"cookedWeight":1600,"portions":4.6,"ingredients":[{"foodId":"bell_pepper","grams":600},{"foodId":"beef_ground_regular","grams":250},{"foodId":"rice_raw","grams":150},{"foodId":"split_peas","grams":100},{"foodId":"onion","grams":150},{"foodId":"parsley","grams":50},{"foodId":"dill","grams":20},{"foodId":"leek","grams":30},{"foodId":"tomato_paste","grams":40},{"foodId":"vegetable_oil","grams":50},{"foodId":"verjuice","grams":30},{"foodId":"sugar","grams":10},{"foodId":"water","grams":350}],"stepsEn":["Half-cook the rice in water and drain it.","Fry the onion in half the oil, add the ground meat, then the rice, cooked split peas, chopped herbs and half the tomato paste.","Cut the tops off the peppers, scoop out the seeds and fill them with the mixture.","Stand them in a pot, pour over the rest of the oil and tomato paste mixed with the water, verjuice and sugar, and simmer covered for 45 minutes."],"stepsFa":["برنج را در آب نیم‌پز و آبکش کن.","پیاز را در نصف روغن تفت بده، گوشت چرخ‌کرده و بعد برنج، لپه‌ی پخته، سبزی خردشده و نصف رب را اضافه کن.","سر فلفل‌ها را ببر، تخمشان را خالی کن و با مواد پر کن.","فلفل‌ها را ایستاده در قابلمه بچین، باقی روغن و رب را با آب، آبغوره و شکر مخلوط کن و رویشان بریز و با درِ بسته ۴۵ دقیقه آرام بپز."],"diet":"meat","pair":"none","planSub":"meat"},
{"id":"jaghur_baghur","titleEn":"Jaghur baghur (fried liver and offal)","titleFa":"جغور بغور","tag":"persian","minutes":40,"meal":"dinner","serving":200,"cookedWeight":900,"portions":4.5,"ingredients":[{"foodId":"beef_liver","grams":300},{"foodId":"lamb","grams":200},{"foodId":"onion","grams":250},{"foodId":"tomato","grams":200},{"foodId":"tomato_paste","grams":30},{"foodId":"vegetable_oil","grams":50}],"stepsEn":["Cut the liver and the meat (heart, kidney) into small cubes.","Fry the onion golden in the oil with turmeric, add the meat and liver and fry over high heat for 10 minutes.","Add the tomato paste and chopped tomato and cook 10 minutes more; season with salt and pepper at the end."],"stepsFa":["جگر و گوشت (دل و قلوه) را ریز و مکعبی خرد کن.","پیاز را با زردچوبه در روغن طلایی کن، گوشت و جگر را اضافه کن و روی حرارت زیاد ۱۰ دقیقه تفت بده.","رب و گوجه‌ی خردشده را اضافه کن و ۱۰ دقیقه‌ی دیگر بپز؛ آخر کار نمک و فلفل بزن."],"diet":"meat","pair":"bread","planSub":"meat"},
{"id":"abgoosht","titleEn":"Abgoosht (dizi)","titleFa":"آبگوشت","tag":"persian","minutes":240,"meal":"lunch","serving":500,"cookedWeight":2500,"portions":5,"ingredients":[{"foodId":"lamb_stew","grams":500},{"foodId":"chickpeas","grams":250},{"foodId":"white_beans","grams":150},{"foodId":"potato","grams":400},{"foodId":"tomato","grams":300},{"foodId":"onion","grams":200},{"foodId":"tomato_paste","grams":40},{"foodId":"dried_lime","grams":15},{"foodId":"water","grams":1000}],"stepsEn":["Simmer the lamb with the onion, dried limes, turmeric and the water for 2 hours.","Add the cooked chickpeas and white beans, the potatoes, tomatoes and tomato paste and simmer 1 hour more.","Pour off the broth to eat with torn bread, and mash the meat, beans and potatoes into goosht-koobideh."],"stepsFa":["گوشت را با پیاز، لیمو عمانی، زردچوبه و آب ۲ ساعت آرام بپز.","نخود و لوبیا سفید پخته، سیب‌زمینی، گوجه و رب را اضافه کن و ۱ ساعت دیگر بپز.","آبش را جدا کن تا با نان ترید کنی، و گوشت و حبوبات و سیب‌زمینی را بکوب تا گوشت‌کوبیده شود."],"diet":"meat","pair":"bread","planSub":"soup"},
{"id":"ash_doogh","titleEn":"Yogurt and herb ash","titleFa":"آش دوغ","tag":"persian","minutes":80,"meal":"lunch","serving":350,"cookedWeight":1850,"portions":5.3,"ingredients":[{"foodId":"yogurt_plain","grams":800},{"foodId":"water","grams":600},{"foodId":"rice_raw","grams":120},{"foodId":"chickpeas","grams":120},{"foodId":"parsley","grams":70},{"foodId":"coriander","grams":60},{"foodId":"dill","grams":40},{"foodId":"leek","grams":70},{"foodId":"egg","grams":50},{"foodId":"onion","grams":120},{"foodId":"vegetable_oil","grams":30}],"stepsEn":["Whisk the yogurt with the water, the egg and a little salt until smooth.","Bring it to a boil over medium heat, stirring all the time in one direction so it does not split.","Add the rice and simmer 30 minutes, then add the chopped herbs and cooked chickpeas and cook 20 minutes more.","Top with the onion fried in the oil and a pinch of dried mint."],"stepsFa":["ماست را با آب، تخم‌مرغ و کمی نمک هم بزن تا یکدست شود.","روی حرارت متوسط بگذار تا بجوشد و مدام در یک جهت هم بزن تا نبُرد.","برنج را اضافه کن و ۳۰ دقیقه بپز، بعد سبزی خردشده و نخود پخته را بریز و ۲۰ دقیقه‌ی دیگر بپز.","با پیاز داغِ سرخ‌شده در روغن و کمی نعناع خشک تزیین کن."],"diet":"vegetarian","allergens":["dairy","egg"],"pair":"none","planSub":"soup"},
{"id":"ash_anar","titleEn":"Pomegranate ash with meatballs","titleFa":"آش انار","tag":"persian","minutes":100,"meal":"lunch","serving":350,"cookedWeight":2150,"portions":6.1,"ingredients":[{"foodId":"pomegranate","grams":400},{"foodId":"pomegranate_paste","grams":80},{"foodId":"rice_raw","grams":120},{"foodId":"split_peas","grams":150},{"foodId":"parsley","grams":100},{"foodId":"coriander","grams":80},{"foodId":"leek","grams":100},{"foodId":"beef_ground_regular_raw","grams":250},{"foodId":"onion","grams":200},{"foodId":"sugar","grams":30},{"foodId":"vegetable_oil","grams":40},{"foodId":"water","grams":1100}],"stepsEn":["Grate half the onion into the ground meat and roll it into small meatballs.","Boil the rice in the water for 20 minutes, add the meatballs and cooked split peas and simmer 20 minutes.","Add the chopped herbs, the juice squeezed from the pomegranate, the pomegranate paste and the sugar; simmer 30 minutes until thick and sweet-sour.","Top with the rest of the onion fried in the oil and a pinch of dried mint."],"stepsFa":["نصف پیاز را در گوشت چرخ‌کرده رنده کن و قلقلی‌های کوچک درست کن.","برنج را ۲۰ دقیقه در آب بجوشان، قلقلی‌ها و لپه‌ی پخته را اضافه کن و ۲۰ دقیقه بپز.","سبزی خردشده، آب انار، رب انار و شکر را بریز و ۳۰ دقیقه بپز تا غلیظ و ملس شود.","با باقی پیازِ سرخ‌شده در روغن و کمی نعناع خشک تزیین کن."],"diet":"meat","pair":"none","planSub":"soup"},
{"id":"sup_morgh","titleEn":"Chicken and vermicelli soup","titleFa":"سوپ مرغ و ورمیشل","tag":"persian","minutes":70,"meal":"dinner","serving":350,"cookedWeight":2000,"portions":5.7,"ingredients":[{"foodId":"chicken_breast","grams":300},{"foodId":"noodle_polo","grams":80},{"foodId":"carrot","grams":150},{"foodId":"onion","grams":100},{"foodId":"celery","grams":50},{"foodId":"parsley","grams":30},{"foodId":"lemon_juice","grams":30},{"foodId":"vegetable_oil","grams":20},{"foodId":"water","grams":1500}],"stepsEn":["Simmer the chicken with half the onion in the water for 40 minutes; lift it out and shred it.","Fry the rest of the onion in the oil, add the grated carrot and chopped celery and pour in the strained broth.","Add the vermicelli and the shredded chicken and simmer 15 minutes.","Stir in the chopped parsley and the lemon juice just before serving."],"stepsFa":["مرغ را با نصف پیاز در آب ۴۰ دقیقه بپز؛ درش بیاور و ریش‌ریش کن.","باقی پیاز را در روغن تفت بده، هویج رنده‌شده و کرفس خردشده را اضافه کن و آب مرغِ صاف‌شده را رویش بریز.","ورمیشل و مرغ ریش‌شده را اضافه کن و ۱۵ دقیقه بپز.","قبل از سرو، جعفری خردشده و آبلیمو را اضافه کن."],"diet":"meat","allergens":["gluten"],"pair":"bread","planSub":"soup"},
{"id":"haleem","titleEn":"Haleem (wheat and meat porridge)","titleFa":"حلیم","tag":"persian","minutes":240,"meal":"breakfast","serving":350,"cookedWeight":1600,"portions":4.6,"ingredients":[{"foodId":"bulgur","grams":250},{"foodId":"lamb_stew","grams":300},{"foodId":"water","grams":1150},{"foodId":"ghee","grams":40},{"foodId":"sugar","grams":40}],"stepsEn":["Soak the bulgur (or whole wheat) overnight, then cook it with the lamb and the water for 3 hours on low heat until very soft.","Take out any bones and pound or blend everything, stirring often, until thick and stretchy.","Serve in bowls topped with the melted ghee, the sugar and cinnamon."],"stepsFa":["بلغور (یا گندم پوست‌کنده) را یک شب خیس کن و بعد با گوشت و آب ۳ ساعت روی حرارت کم بپز تا کاملاً له شود.","استخوان‌ها را دربیاور و همه را بکوب یا با گوشت‌کوب برقی بزن و مدام هم بزن تا غلیظ و کش‌دار شود.","در کاسه بکش و با روغن حیوانی داغ، شکر و دارچین سرو کن."],"diet":"meat","allergens":["gluten","dairy"],"pair":"none","planSub":"soup"},
{"id":"eshkeneh","titleEn":"Eshkeneh (onion and egg soup)","titleFa":"اشکنه","tag":"persian","minutes":45,"meal":"dinner","serving":350,"cookedWeight":1500,"portions":4.3,"ingredients":[{"foodId":"onion","grams":250},{"foodId":"vegetable_oil","grams":45},{"foodId":"flour_white","grams":20},{"foodId":"fenugreek","grams":40},{"foodId":"potato","grams":300},{"foodId":"egg","grams":150},{"foodId":"water","grams":1000}],"stepsEn":["Fry the sliced onion golden in the oil with turmeric; add the flour and the chopped fenugreek (or a spoonful of dried) and stir for 1 minute.","Add the water and potato cubes and simmer 25 minutes until the potato is soft.","Break the eggs into the soup one by one without stirring and cook 5 minutes until set."],"stepsFa":["پیاز خلالی را با زردچوبه در روغن طلایی کن؛ آرد و شنبلیله‌ی خردشده (یا یک قاشق شنبلیله‌ی خشک) را اضافه کن و ۱ دقیقه تفت بده.","آب و سیب‌زمینی مکعبی را اضافه کن و ۲۵ دقیقه بپز تا سیب‌زمینی نرم شود.","تخم‌مرغ‌ها را یکی‌یکی در آش بشکن، هم نزن و ۵ دقیقه بپز تا ببندد."],"diet":"vegetarian","allergens":["egg","gluten"],"pair":"bread","planSub":"soup"},
{"id":"kalleh_joosh","titleEn":"Kalleh joosh (kashk and walnut soup)","titleFa":"کله‌جوش","tag":"persian","minutes":30,"meal":"dinner","serving":250,"cookedWeight":1000,"portions":4,"ingredients":[{"foodId":"kashk","grams":300},{"foodId":"walnuts","grams":60},{"foodId":"onion","grams":250},{"foodId":"vegetable_oil","grams":50},{"foodId":"water","grams":500}],"stepsEn":["Fry the sliced onion golden in the oil with turmeric and a spoon of dried mint.","Add the chopped walnuts and the water and simmer 10 minutes.","Stir in the kashk, let it just come to a boil and serve with bread torn into the bowl."],"stepsFa":["پیاز خلالی را با زردچوبه و یک قاشق نعناع خشک در روغن طلایی کن.","گردوی خردشده و آب را اضافه کن و ۱۰ دقیقه بپز.","کشک را هم بزن، بگذار فقط یک جوش بزند و با نان ترید سرو کن."],"diet":"vegetarian","allergens":["dairy","nuts"],"pair":"bread","planSub":"soup"},
{"id":"kashk_bademjan","titleEn":"Kashk-e bademjan (eggplant with kashk)","titleFa":"کشک بادمجان","tag":"persian","minutes":60,"meal":"dinner","serving":250,"cookedWeight":1000,"portions":4,"ingredients":[{"foodId":"eggplant","grams":700},{"foodId":"kashk","grams":150},{"foodId":"onion","grams":200},{"foodId":"garlic","grams":20},{"foodId":"walnuts","grams":40},{"foodId":"vegetable_oil","grams":80}],"stepsEn":["Peel the eggplants, fry them in most of the oil until golden and soft, then mash them.","Fry the onion and garlic in the rest of the oil; set some aside for the top, and cook the rest with the eggplant and a little water for 10 minutes.","Stir in most of the kashk and the chopped walnuts.","Serve topped with the rest of the kashk, the fried onion and dried mint sizzled in oil."],"stepsFa":["بادمجان‌ها را پوست بگیر، در بیشتر روغن سرخ کن تا طلایی و نرم شوند و بعد له کن.","پیاز و سیر را در باقی روغن تفت بده؛ کمی برای تزیین کنار بگذار و بقیه را با بادمجان و کمی آب ۱۰ دقیقه بپز.","بیشتر کشک و گردوی خردشده را هم بزن.","با باقی کشک، پیاز داغ و نعناع داغ رویش سرو کن."],"diet":"vegetarian","allergens":["dairy","nuts"],"pair":"bread","planSub":"veg"},
{"id":"borani_esfenaj","titleEn":"Spinach borani (spinach and yogurt)","titleFa":"بورانی اسفناج","tag":"persian","minutes":25,"meal":"dinner","serving":200,"cookedWeight":850,"portions":4.3,"ingredients":[{"foodId":"spinach","grams":500},{"foodId":"yogurt_plain","grams":500},{"foodId":"onion","grams":100},{"foodId":"garlic","grams":10},{"foodId":"vegetable_oil","grams":25}],"stepsEn":["Wash and chop the spinach and wilt it in a dry pan; squeeze out the water and let it cool.","Fry the onion and garlic in the oil until golden and mix them with the spinach.","Stir everything into the yogurt with salt and pepper and chill before serving."],"stepsFa":["اسفناج را بشور، خرد کن و در تابه‌ی خشک بپز تا بخوابد؛ آبش را بگیر و بگذار خنک شود.","پیاز و سیر را در روغن طلایی کن و با اسفناج مخلوط کن.","همه را با نمک و فلفل در ماست هم بزن و قبل از سرو خنک کن."],"diet":"vegetarian","allergens":["dairy"],"pair":"bread","planSub":"veg"},
{"id":"borani_bademjan","titleEn":"Eggplant borani (eggplant and yogurt)","titleFa":"بورانی بادمجان","tag":"persian","minutes":35,"meal":"dinner","serving":200,"cookedWeight":1000,"portions":5,"ingredients":[{"foodId":"eggplant","grams":500},{"foodId":"yogurt_plain","grams":500},{"foodId":"garlic","grams":15},{"foodId":"vegetable_oil","grams":50},{"foodId":"walnuts","grams":20}],"stepsEn":["Slice the eggplant, fry it golden in the oil and mash it with a fork.","Mix it with the yogurt, the crushed garlic, salt and pepper.","Serve cold, topped with the chopped walnuts (and a little saffron or dried mint)."],"stepsFa":["بادمجان را حلقه کن، در روغن طلایی سرخ کن و با چنگال له کن.","با ماست، سیر له‌شده، نمک و فلفل مخلوط کن.","سرد و با گردوی خردشده (و کمی زعفران یا نعناع خشک) رویش سرو کن."],"diet":"vegetarian","allergens":["dairy","nuts"],"pair":"bread","planSub":"veg"},
{"id":"mast_o_khiar","titleEn":"Yogurt with cucumber","titleFa":"ماست و خیار","tag":"persian","minutes":10,"meal":"snack","serving":200,"cookedWeight":810,"portions":4.1,"ingredients":[{"foodId":"yogurt_plain","grams":500},{"foodId":"cucumber","grams":250},{"foodId":"walnuts","grams":30},{"foodId":"raisins","grams":30}],"stepsEn":["Dice or grate the cucumber.","Stir it into the yogurt with the raisins, chopped walnuts, dried mint and a pinch of salt.","Chill for 30 minutes before serving (dried rose petals on top are traditional)."],"stepsFa":["خیار را ریز خرد یا رنده کن.","با کشمش، گردوی خردشده، نعناع خشک و کمی نمک در ماست هم بزن.","۳۰ دقیقه در یخچال بگذار و بعد سرو کن (گل‌محمدی خشک رویش هم رسم است)."],"diet":"vegetarian","allergens":["dairy","nuts"],"pair":"none","planSub":"veg"},
{"id":"yatimcheh","titleEn":"Yatimcheh (eggplant and tomato stew)","titleFa":"یتیمچه","tag":"persian","minutes":50,"meal":"dinner","serving":250,"cookedWeight":1100,"portions":4.4,"ingredients":[{"foodId":"eggplant","grams":600},{"foodId":"tomato","grams":400},{"foodId":"onion","grams":200},{"foodId":"garlic","grams":20},{"foodId":"vegetable_oil","grams":70},{"foodId":"tomato_paste","grams":20}],"stepsEn":["Peel and cube the eggplant and fry it golden in most of the oil.","Fry the onion and garlic in the rest of the oil with turmeric, then add the tomato paste and chopped tomato.","Add the eggplant and simmer covered for 20 minutes on low heat."],"stepsFa":["بادمجان را پوست بگیر، مکعبی خرد کن و در بیشتر روغن طلایی سرخ کن.","پیاز و سیر را با زردچوبه در باقی روغن تفت بده، بعد رب و گوجه‌ی خردشده را اضافه کن.","بادمجان را اضافه کن و با درِ بسته ۲۰ دقیقه روی حرارت کم بپز."],"diet":"vegan","pair":"bread","planSub":"veg"},
{"id":"baghala_ghatogh","titleEn":"Baghala ghatogh (fava beans with dill and egg)","titleFa":"باقلا قاتق","tag":"persian","minutes":40,"meal":"lunch","serving":250,"cookedWeight":1000,"portions":4,"ingredients":[{"foodId":"fava_beans","grams":600},{"foodId":"dill","grams":100},{"foodId":"garlic","grams":30},{"foodId":"egg","grams":150},{"foodId":"vegetable_oil","grams":45},{"foodId":"water","grams":200}],"stepsEn":["Fry the crushed garlic in the oil with turmeric, add the chopped dill and fry 2 minutes.","Add the cooked fava beans and the water and simmer 15 minutes.","Break the eggs over the top, cover and cook until just set; serve with rice."],"stepsFa":["سیر له‌شده را با زردچوبه در روغن تفت بده، شوید خردشده را اضافه کن و ۲ دقیقه تفت بده.","باقلای پخته و آب را اضافه کن و ۱۵ دقیقه بپز.","تخم‌مرغ‌ها را رویش بشکن، درش را بگذار تا تازه ببندد و با کته سرو کن."],"diet":"vegetarian","allergens":["egg"],"pair":"rice","planSub":"legume"},
{"id":"kuku_sabzi","titleEn":"Herb kuku","titleFa":"کوکو سبزی","tag":"persian","minutes":50,"meal":"dinner","serving":120,"cookedWeight":800,"portions":6.7,"ingredients":[{"foodId":"parsley","grams":150},{"foodId":"coriander","grams":150},{"foodId":"dill","grams":80},{"foodId":"leek","grams":150},{"foodId":"egg","grams":300},{"foodId":"walnuts","grams":40},{"foodId":"barberries","grams":20},{"foodId":"flour_white","grams":15},{"foodId":"vegetable_oil","grams":70},{"foodId":"garlic","grams":10}],"stepsEn":["Wash, dry and finely chop the herbs.","Beat the eggs with the flour, turmeric, salt and pepper; mix in the herbs, garlic, walnuts and barberries.","Heat the oil in a pan, pour in the mixture, cover and cook 20 minutes on low heat.","Cut it into four, turn the pieces and cook 10 minutes more."],"stepsFa":["سبزی‌ها را بشور، خشک کن و ریز خرد کن.","تخم‌مرغ‌ها را با آرد، زردچوبه، نمک و فلفل بزن؛ سبزی، سیر، گردو و زرشک را اضافه کن.","روغن را در تابه داغ کن، مواد را بریز، درش را بگذار و ۲۰ دقیقه روی حرارت کم بپز.","چهار قسمت کن، برگردان و ۱۰ دقیقه‌ی دیگر بپز."],"diet":"vegetarian","allergens":["egg","nuts","gluten"],"pair":"bread","planSub":"egg"},
{"id":"kuku_sibzamini","titleEn":"Potato kuku","titleFa":"کوکو سیب‌زمینی","tag":"persian","minutes":45,"meal":"dinner","serving":120,"cookedWeight":850,"portions":7.1,"ingredients":[{"foodId":"potato","grams":600},{"foodId":"egg","grams":200},{"foodId":"onion","grams":100},{"foodId":"flour_white","grams":20},{"foodId":"vegetable_oil","grams":80}],"stepsEn":["Boil, peel and grate the potatoes; grate the onion and squeeze out its juice.","Mix them with the eggs, flour, turmeric, salt and pepper.","Shape small patties and fry them in the oil, 3 minutes a side, until golden."],"stepsFa":["سیب‌زمینی‌ها را آب‌پز کن، پوست بگیر و رنده کن؛ پیاز را رنده کن و آبش را بگیر.","با تخم‌مرغ، آرد، زردچوبه، نمک و فلفل مخلوط کن.","کوکوهای کوچک درست کن و در روغن، هر طرف ۳ دقیقه سرخ کن تا طلایی شوند."],"diet":"vegetarian","allergens":["egg","gluten"],"pair":"bread","planSub":"egg"},
{"id":"omelet_gojeh","titleEn":"Tomato omelette","titleFa":"املت گوجه‌فرنگی","tag":"persian","minutes":20,"meal":"breakfast","serving":300,"cookedWeight":650,"portions":2.2,"ingredients":[{"foodId":"egg","grams":200},{"foodId":"tomato","grams":500},{"foodId":"onion","grams":100},{"foodId":"vegetable_oil","grams":25},{"foodId":"tomato_paste","grams":15}],"stepsEn":["Fry the chopped onion in the oil until soft.","Add the peeled, chopped tomatoes and the tomato paste and cook 10 minutes until the water is gone.","Break in the eggs, season and stir gently for 2–3 minutes until just set."],"stepsFa":["پیاز خردشده را در روغن تفت بده تا نرم شود.","گوجه‌ی پوست‌کنده و خردشده و رب را اضافه کن و ۱۰ دقیقه بپز تا آبش کشیده شود.","تخم‌مرغ‌ها را بشکن، نمک و فلفل بزن و ۲ تا ۳ دقیقه آرام هم بزن تا تازه ببندد."],"diet":"vegetarian","allergens":["egg"],"pair":"bread","planSub":"egg"},
{"id":"khagineh","titleEn":"Khagineh (sweet saffron omelette)","titleFa":"خاگینه","tag":"persian","minutes":25,"meal":"breakfast","serving":130,"cookedWeight":390,"portions":3,"ingredients":[{"foodId":"egg","grams":200},{"foodId":"flour_white","grams":20},{"foodId":"milk_whole","grams":50},{"foodId":"saffron_brewed","grams":10},{"foodId":"butter","grams":25},{"foodId":"sugar","grams":60},{"foodId":"water","grams":60},{"foodId":"rose_water","grams":10}],"stepsEn":["Boil the sugar and water for 5 minutes into a light syrup and stir in the rose water.","Beat the eggs with the flour, milk and saffron until smooth.","Cook the batter in the butter over low heat, covered, until set; cut it into pieces and turn them.","Pour the syrup over and let it soak in for 5 minutes."],"stepsFa":["شکر و آب را ۵ دقیقه بجوشان تا شربت رقیقی شود و گلاب را اضافه کن.","تخم‌مرغ‌ها را با آرد، شیر و زعفران بزن تا یکدست شود.","مواد را روی حرارت کم در کره با درِ بسته بپز تا ببندد؛ برش بزن و برگردان.","شربت را رویش بریز و بگذار ۵ دقیقه به خوردش برود."],"diet":"vegetarian","allergens":["egg","gluten","dairy"],"pair":"bread","planSub":"egg"},
{"id":"salad_olivieh","titleEn":"Olivieh salad (chicken and potato salad)","titleFa":"سالاد الویه","tag":"persian","minutes":60,"meal":"dinner","serving":250,"cookedWeight":1500,"portions":6,"ingredients":[{"foodId":"chicken_breast","grams":300},{"foodId":"potato","grams":500},{"foodId":"egg","grams":200},{"foodId":"peas_green","grams":100},{"foodId":"carrot","grams":100},{"foodId":"cucumber","grams":150},{"foodId":"mayonnaise","grams":150},{"foodId":"lemon_juice","grams":15}],"stepsEn":["Boil the chicken, potatoes, eggs and carrots, and let them cool.","Shred the chicken, and grate or finely dice the potatoes, eggs, carrots and cucumber (or pickles).","Mix everything with the cooked peas, mayonnaise, lemon juice, salt and pepper and chill for 1 hour."],"stepsFa":["مرغ، سیب‌زمینی، تخم‌مرغ و هویج را آب‌پز کن و بگذار خنک شوند.","مرغ را ریش‌ریش کن و سیب‌زمینی، تخم‌مرغ، هویج و خیار (یا خیارشور) را رنده یا ریز خرد کن.","همه را با نخودفرنگی پخته، سس مایونز، آبلیمو، نمک و فلفل مخلوط کن و ۱ ساعت در یخچال بگذار."],"diet":"meat","allergens":["egg"],"pair":"bread","planSub":"poultry"},
{"id":"falafel","titleEn":"Falafel","titleFa":"فلافل","tag":"persian","minutes":40,"meal":"dinner","serving":120,"cookedWeight":950,"portions":7.9,"ingredients":[{"foodId":"chickpeas_raw","grams":400},{"foodId":"water","grams":400},{"foodId":"onion","grams":100},{"foodId":"garlic","grams":20},{"foodId":"parsley","grams":50},{"foodId":"coriander","grams":50},{"foodId":"vegetable_oil","grams":130}],"stepsEn":["Soak the chickpeas overnight in plenty of water and drain them; do not cook them.","Grind them with the onion, garlic, herbs, salt, cumin and a pinch of baking soda to a coarse paste.","Shape small balls and deep-fry them in hot oil for 3–4 minutes until dark golden."],"stepsFa":["نخود را یک شب در آب فراوان خیس کن و آبکش کن؛ نپزش.","با پیاز، سیر، سبزی، نمک، زیره و کمی جوش‌شیرین چرخ کن تا خمیر درشتی شود.","گلوله‌های کوچک درست کن و ۳ تا ۴ دقیقه در روغن داغ سرخ کن تا طلایی تیره شوند."],"diet":"vegan","pair":"bread","planSub":"legume"},
{"id":"sholeh_zard","titleEn":"Sholeh zard (saffron rice pudding)","titleFa":"شله‌زرد","tag":"persian","minutes":120,"meal":"snack","serving":200,"cookedWeight":2000,"portions":10,"ingredients":[{"foodId":"rice_raw","grams":250},{"foodId":"water","grams":1500},{"foodId":"sugar","grams":300},{"foodId":"saffron_brewed","grams":40},{"foodId":"rose_water","grams":60},{"foodId":"butter","grams":30},{"foodId":"almonds","grams":30},{"foodId":"pistachio","grams":15}],"stepsEn":["Simmer the soaked rice in the water for 1 hour until very soft and sticky.","Stir in the sugar and cook 20 minutes more, stirring.","Add the butter, saffron, rose water and slivered almonds and cook 15 minutes on low heat.","Pour into bowls and decorate with cinnamon and pistachio slivers."],"stepsFa":["برنج خیس‌خورده را ۱ ساعت در آب بپز تا کاملاً نرم و لعاب‌دار شود.","شکر را اضافه کن و ۲۰ دقیقه‌ی دیگر هم بزن و بپز.","کره، زعفران، گلاب و خلال بادام را اضافه کن و ۱۵ دقیقه روی حرارت کم بپز.","در کاسه بکش و با دارچین و خلال پسته تزیین کن."],"diet":"vegetarian","allergens":["dairy","nuts"],"pair":"none","planSub":"sweet"},
{"id":"shir_berenj","titleEn":"Shir berenj (milk rice pudding)","titleFa":"شیربرنج","tag":"persian","minutes":70,"meal":"snack","serving":250,"cookedWeight":1400,"portions":5.6,"ingredients":[{"foodId":"rice_raw","grams":150},{"foodId":"water","grams":400},{"foodId":"milk_whole","grams":1000},{"foodId":"sugar","grams":60},{"foodId":"rose_water","grams":20}],"stepsEn":["Cook the rice in the water for 20 minutes until the water is absorbed.","Add the milk and simmer 40 minutes on low heat, stirring often, until creamy.","Stir in the sugar and rose water; serve warm or cold with a little cinnamon."],"stepsFa":["برنج را ۲۰ دقیقه در آب بپز تا آبش کشیده شود.","شیر را اضافه کن و ۴۰ دقیقه روی حرارت کم بپز و مرتب هم بزن تا خامه‌ای شود.","شکر و گلاب را هم بزن؛ گرم یا سرد با کمی دارچین سرو کن."],"diet":"vegetarian","allergens":["dairy"],"pair":"none","planSub":"sweet"},
{"id":"fereni","titleEn":"Fereni (rice flour milk pudding)","titleFa":"فرنی","tag":"persian","minutes":25,"meal":"breakfast","serving":250,"cookedWeight":1050,"portions":4.2,"ingredients":[{"foodId":"rice_raw","grams":60},{"foodId":"milk_whole","grams":1000},{"foodId":"sugar","grams":80},{"foodId":"rose_water","grams":20}],"stepsEn":["Grind the rice to a fine flour and dissolve it in a glass of the cold milk.","Heat the rest of the milk with the sugar, pour in the rice mixture and stir over low heat for 15 minutes until thick.","Add the rose water, pour into bowls and serve warm or cold."],"stepsFa":["برنج را آسیاب کن تا آرد نرمی شود و در یک لیوان از شیرِ سرد حل کن.","باقی شیر را با شکر گرم کن، مخلوط آرد برنج را بریز و روی حرارت کم ۱۵ دقیقه هم بزن تا غلیظ شود.","گلاب را اضافه کن، در کاسه بریز و گرم یا سرد سرو کن."],"diet":"vegetarian","allergens":["dairy"],"pair":"none","planSub":"sweet"},
{"id":"kachi","titleEn":"Kachi (saffron flour pudding)","titleFa":"کاچی","tag":"persian","minutes":30,"meal":"breakfast","serving":150,"cookedWeight":900,"portions":6,"ingredients":[{"foodId":"flour_white","grams":120},{"foodId":"ghee","grams":80},{"foodId":"sugar","grams":150},{"foodId":"water","grams":600},{"foodId":"saffron_brewed","grams":20},{"foodId":"rose_water","grams":30}],"stepsEn":["Boil the water with the sugar, saffron and rose water into a thin syrup.","Roast the flour in the ghee over low heat for 15 minutes, stirring, until golden and fragrant.","Slowly pour the syrup into the flour, stirring hard, and cook 5 minutes until smooth and thick."],"stepsFa":["آب را با شکر، زعفران و گلاب بجوشان تا شربت رقیقی شود.","آرد را در روغن حیوانی روی حرارت کم ۱۵ دقیقه تفت بده تا طلایی و معطر شود.","شربت را آرام‌آرام روی آرد بریز، محکم هم بزن و ۵ دقیقه بپز تا یکدست و غلیظ شود."],"diet":"vegetarian","allergens":["gluten","dairy"],"pair":"none","planSub":"sweet"}];
